head.script:
scwin.gVar = {
    "cNextTabIDTarget" : "",
    "cNextTabIDInput" : "",
    "cNextTabIDButton" : "",
    "cNextTabIDSelectBox" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > nextTabID]<br/>Tab 키로 포커스 이동 시 포커스가 이동될 다음 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "포커스가 이동될 컴포넌트의 ID 를 문자열로 설정할 수 있어야 합니다.",
        "존재하지 않는 ID 설정 시 적용되지 않고 일반적인 tabIndex 규칙을 따라야 합니다.",
        "다른 Scope 의 컴포넌트는 nextTabID 로 설정할 수 없어야 합니다.",
        "미설정 시 일반적인 tabIndex 규칙을 따라야 합니다.",
        "tabIndex 속성에 의한 순서는 무시되고 nextTabID 에 설정된 컴포넌트로 포커스가 이동되어야 합니다.",
        "Shift+Tab 키로 포커스를 이전으로 이동하면 현재 포커스된 컴포넌트를 nextTabID 속성에 설정한 컴포넌트로 포커스가 이동되어야 합니다.",
        "현재 포커스된 컴포넌트가 두 개 이상의 nextTabID 에 설정된 경우 소스에서 마지막에 정의된 컴포넌트로 포커스가 이동되어야 합니다.",
        "nextTabID 대상이 포커스 불가 상태(disabled 등)이고 해당 대상에 nextTabID 가 설정되어 있으면 다음 컴포넌트로 포커스가 이동되어야 합니다.",
        "nextTabID 대상이 포커스 불가 상태(disabled 등)이고 해당 대상에 nextTabID 가 설정되어 있지 않으면 tabIndex 속성과 관계없이 포커스가 이동하지 않아야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 기존 button2 있으면 삭제
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    // 기존 selectbox2 있으면 삭제
    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    // 조건 설정 (target)
    let properties = {
        tabIndex: 2,
        nextTabID: scwin.gVar["cNextTabIDTarget"],
    };

    let cList = $c.gcm.createCList(properties);

    // 조건 설정 (input)
    let properties_input = {
        tabIndex: 3,
        nextTabID: scwin.gVar["cNextTabIDInput"],
    };

    let cList_input = $c.gcm.createCList(properties_input);

    // 조건 설정 (button)
    let properties_button = {
        tabIndex: 4,
        nextTabID: scwin.gVar["cNextTabIDButton"],
    };

    let cList_button = $c.gcm.createCList(properties_button);

    // 조건 설정 (selectbox)
    let properties_selectbox = {
        tabIndex: 5,
        nextTabID: scwin.gVar["cNextTabIDSelectBox"],
    };

    let cList_selectbox = $c.gcm.createCList(properties_selectbox);

    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");
    $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");
    $c.gcm.createBasicSelectBox(cList_selectbox, 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");
    $c.gcm.createBasicTextArea(cList, 'ev:onfocus="scwin.target1_onfocus"')

    target1.setValue("target");
    input2.setValue("input");
    scwin.changeDisplay();
}



scwin.changeDisplay = function() {
    // ID에 "target1"을 포함하는 요소 선택
    var elements = document.querySelectorAll('[id*="target1"]');

    // 선택된 모든 요소에 대해 display 속성 변경
    elements.forEach(function(element) {
        element.style.display = 'block';
    });
}
